import { useEffect, useState } from 'react'
import Logo from '../Logo'
import { api, isMock } from '../../api/client'
import { EVENT, SCHOOL } from '../../config/event'

/** On-screen preview of the certificate. The real PDF is generated by Flask (same layout). */
export default function CertificateModal({ p, onClose, toast }) {
  const [busy, setBusy] = useState(false)
  useEffect(() => {
    const esc = (e) => e.key === 'Escape' && onClose()
    window.addEventListener('keydown', esc); return () => window.removeEventListener('keydown', esc)
  }, [onClose])

  const download = async () => {
    setBusy(true)
    try { await api.downloadPdf(p.id); toast('PDF downloaded') } catch (err) { toast(err.message) } finally { setBusy(false) }
  }

  return (
    <div className="modal" role="dialog" aria-modal="true" aria-label={`Certificate for ${p.name}`} onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal-in">
        <div className="cert"><div className="frame" /><div className="in">
          <Logo size={52} className="clogo" />
          <div className="t2">{SCHOOL.name.toUpperCase()} PRESENTS</div>
          <div className="t1">Certificate of Participation</div>
          <div className="tx">This certificate is proudly presented to</div>
          <div className="nm">{p.name}</div>
          <div className="tx">for taking part in <b>{EVENT.name} {EVENT.year}</b>, the robotics showcase held on {EVENT.dateLabel} at {EVENT.venue}.</div>
          <div className="cid">Entry ID: {p.id}</div>
          <div className="sig"><div>Principal</div><div>Event Coordinator</div></div>
        </div></div>
        <div className="modal-bar">
          {isMock && <span className="demo">Preview only. The real app downloads a PDF made by Flask.</span>}
          <button className="btn" type="button" onClick={download} disabled={busy}>{busy ? 'Preparing…' : 'Download PDF'}</button>
          <button className="btn line" type="button" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  )
}
